// ════════════════════════════════════════════════════════════════════
//  วัด "กระดาษบนจอ → ภาพ" ในแอปจริง — เครื่องมือวัด ยังไม่ใช่ตัวอัดคลิป
//
//      THAISCORE_SELFTEST_PIPE=1 THAISCORE_SELFTEST_SCORE=/path/x.thscore
//
//  ★ ต่อจากการวัดท่อ (ดู pipe_bench.ts) ซึ่งพบว่า **ท่อไม่ใช่คอขวด**
//    ตัวที่เหลือให้วัดคือฝั่งวาด · รวมสองส่วนแล้วถึงจะรู้ว่าคลิป 3 นาทีต้องรอกี่นาที
//
//  ★★ ฝังฟอนต์เป็น data URI ก่อน rasterize เสมอ ★★
//    ภาพที่วาดจาก <foreignObject> **ไม่เห็นฟอนต์ของหน้า** — สัญลักษณ์โน้ตสากล
//    (Bravura) จะกลายเป็นกล่องว่าง และตัวไทยตกไปใช้ฟอนต์แทนของระบบ
//    บนจอดูถูกทุกอย่าง แต่ในภาพที่อัดออกมาผิด (พิสูจน์ไว้แล้ว 2026-08-17)
//    → ราคาส่วนนี้จ่ายครั้งเดียวต่อคลิป ไม่ใช่ต่อเฟรม จึงวัดแยก
// ════════════════════════════════════════════════════════════════════
import { invoke } from '@tauri-apps/api/core';

const report = (msg: string) => { void invoke('selftest_report', { msg }).catch(() => {}); };
const ms = (n: number) => n.toFixed(1);
const forClip = (per: number) => `${((per * 5400) / 60000).toFixed(1)} นาที`;
import {
  decode, embedFontCss, pageCss, rootVars, svgDirect, svgFor,
} from './clip_raster';

const mid = (a: number[]) => [...a].sort((x, y) => x - y)[Math.floor(a.length / 2)];


export async function runRasterBench(mode = '1') {
  // ★ รอให้กระดาษวาดจริงก่อน — เพลงถูกเปิดโดย THAISCORE_SELFTEST_SCORE ซึ่งวิ่งขนานกัน
  let paper: HTMLElement | null = null;
  for (let i = 0; i < 100 && !paper; i += 1) {
    paper = document.querySelector('.tn-sheet');
    if (!paper) await new Promise((r) => setTimeout(r, 100));
  }
  if (!paper) { report('⚠ ไม่มีกระดาษบนจอ — ข้ามการวัดฝั่งวาด (ตั้ง THAISCORE_SELFTEST_SCORE ด้วยไหม)'); return; }
  await new Promise((r) => setTimeout(r, 800));

  report('══ วัดฝั่งวาด: กระดาษบนจอ → ภาพ ══');

  const t0 = performance.now();
  const font = await embedFontCss();
  const tFont = performance.now() - t0;
  const t1 = performance.now();
  const css = `${font.css}\n${pageCss()}`;
  const vars = rootVars();
  const tCss = performance.now() - t1;
  report(`ฝังฟอนต์ ${font.count} ก้อน = ${(font.bytes / 1048576).toFixed(2)} MB · ${ms(tFont)} ms`);
  report(`ฝัง CSS ของหน้า ${(css.length / 1048576).toFixed(2)} MB · ตัวแปรราก ${vars.split(';').length} ตัว `
    + `· ${ms(tCss)} ms — **ทั้งสองอย่างจ่ายครั้งเดียวต่อคลิป ไม่ใช่ต่อเฟรม**`);

  // ── ★ ไล่หาว่าอะไรทำภาพพัง — ทีละชั้น แทนการเดา ─────────────────
  if (!mode.startsWith('samples')) {
    const sheets = Array.from(document.styleSheets);
    const cssOf = (only?: CSSStyleSheet) => {
      const out: string[] = [];
      for (const sh of sheets) {
        if (only && sh !== only) continue;
        let rules: CSSRuleList;
        try { rules = sh.cssRules; } catch { continue; }
        for (const r of Array.from(rules)) { if (!(r instanceof CSSFontFaceRule)) out.push(r.cssText); }
      }
      return out.join('\n');
    };
    const boxD = paper.getBoundingClientRect();
    const tryIt = async (label: string, cssTry: string, varsTry: string) => {
      try {
        await decode(svgFor(paper, { w: boxD.width, h: boxD.height }, { w: boxD.width, h: boxD.height }, cssTry, varsTry));
        report(`   ลอง ${label} (${(cssTry.length / 1024).toFixed(0)} KB) → ผ่าน`);
        return true;
      } catch {
        report(`   ลอง ${label} (${(cssTry.length / 1024).toFixed(0)} KB) → ✗ พัง`);
        return false;
      }
    };
    report('ไล่หาต้นเหตุภาพพัง:');
    await tryIt('ฟอนต์อย่างเดียว', font.css, '');
    await tryIt('ฟอนต์ + ตัวแปรราก', font.css, vars);
    await tryIt('CSS ของหน้าอย่างเดียว', cssOf(), '');
    for (let i = 0; i < sheets.length; i += 1) {
      const one = cssOf(sheets[i] as CSSStyleSheet);
      if (!one) continue;
      await tryIt(`สไตล์ชีตที่ ${i + 1}: ${(sheets[i].href || 'ฝังในหน้า').split('/').pop()}`, one, '');
    }
  }

  const W = 1080; const H = 1920;
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d', { willReadFrequently: true })!;
  const box = paper.getBoundingClientRect();

  // ── ก · วาดใหม่ทั้งใบทุกเฟรม (ทางตรงไปตรงมา) ────────────────────
  // ★ โหมด samples ข้ามการวัดเวลาทั้งหมด — ต้องการแค่ภาพกระดาษที่แคชไว้
  const SER: number[] = []; const DEC: number[] = []; const DRAW: number[] = []; const PIX: number[] = [];
  const N = mode.startsWith('samples') ? 0 : 12;
  let svgBytes = 0; let failed = '';
  for (let i = 0; i < (mode.startsWith('samples') ? 0 : N + 2); i += 1) {
    try {
      const a = performance.now();
      const svg = svgFor(paper, { w: box.width, h: box.height }, { w: box.width, h: box.height }, css, vars);
      const b = performance.now();
      const img = await decode(svg);
      const c = performance.now();
      ctx.fillStyle = '#fffdf7'; ctx.fillRect(0, 0, W, H);
      ctx.drawImage(img, 0, 0, W, Math.round((W / box.width) * box.height));
      const d = performance.now();
      ctx.getImageData(0, 0, W, H);
      const e = performance.now();
      svgBytes = svg.length;
      if (i < 2) continue;                      // ทิ้งใบอุ่นเครื่อง
      SER.push(b - a); DEC.push(c - b); DRAW.push(d - c); PIX.push(e - d);
    } catch (err) { failed = String(err).slice(0, 120); break; }
  }
  if (failed) { report(`⚠ วาดไม่สำเร็จ: ${failed}`); return; }

  const s = mid(SER) || 0; const dcd = mid(DEC) || 0; const dr = mid(DRAW) || 0; const px = mid(PIX) || 0;
  const whole = s + dcd + dr + px;
  if (!mode.startsWith('samples')) {
    report(`วาดใหม่ทั้งใบ: แปลง DOM ${ms(s)} ms · ถอดภาพ ${ms(dcd)} ms · วางลง canvas ${ms(dr)} ms `
      + `· ดึงพิกเซล ${ms(px)} ms = ${ms(whole)} ms/ใบ (SVG ${(svgBytes / 1024).toFixed(0)} KB)`);
  }

  // ── ข · แคชภาพกระดาษ แล้ววาดทับเฉพาะไฮไลต์ ─────────────────────
  //   ★ ระหว่างเล่นเพลง กระดาษ **ไม่เปลี่ยน** เปลี่ยนแค่ตำแหน่งหัวเข็ม
  const cached = await decode(svgFor(paper, { w: box.width, h: box.height }, { w: box.width, h: box.height }, css, vars));
  const FAST: number[] = [];
  for (let i = 0; i < (mode.startsWith('samples') ? 0 : N + 2); i += 1) {
    const a = performance.now();
    ctx.drawImage(cached, 0, 0, W, Math.round((W / box.width) * box.height));
    ctx.fillStyle = 'rgba(224,168,46,.35)';
    ctx.fillRect((i * 37) % W, 200, 90, 120);          // หัวเข็มสมมุติ
    ctx.getImageData(0, 0, W, H);
    if (i >= 2) FAST.push(performance.now() - a);
  }
  const fast = mid(FAST) || 0;
  if (!mode.startsWith('samples')) {
    report(`แคชกระดาษ + วาดทับไฮไลต์: ${ms(fast)} ms/ใบ = เร็วกว่า ${(whole / fast).toFixed(1)} เท่า`);
    const SEND = 21;
    report(`รวมทั้งเส้น (พิกเซลดิบ 1080p · ส่ง ${SEND} ms):`);
    report(`   วาดใหม่ทุกใบ  ${ms(whole + SEND)} ms/ใบ → คลิป 3 นาทีรอ ${forClip(whole + SEND)}`);
    report(`   แคชกระดาษไว้  ${ms(fast + SEND)} ms/ใบ → คลิป 3 นาทีรอ ${forClip(fast + SEND)}`);
  }
  // ── ★★ ตรวจ "หน้าตาถูกไหม" ไม่ใช่แค่ "เร็วแค่ไหน" ★★ ────────────
  //   เร็วแต่ได้กล่องว่างแทนสัญลักษณ์โน้ตสากล = ใช้ไม่ได้เลย
  //   ส่งภาพจริงออกไปให้คนเปิดดูด้วยตา — เครื่องตรวจแทนไม่ได้
  if (!mode.startsWith('samples')) try {
    await invoke('pipe_reset');
    // วาดทั้งกระดาษไทยและแผ่นสากลลงใบเดียว เพื่อให้เห็นฟอนต์ทั้งสองตระกูลพร้อมกัน
    const wn = document.querySelector('.wn-host svg') as SVGElement | null;
    ctx.fillStyle = '#fffdf7'; ctx.fillRect(0, 0, W, H);
    const thaiH = Math.round((W / box.width) * box.height);
    ctx.drawImage(cached, 0, 0, W, thaiH);
    if (wn) {
      const t = performance.now();
      const d = svgDirect(wn, css, vars);
      const wimg = await decode(d.svg);
      report(`แผ่นสากล: ${d.w}×${d.h} · SVG ${(d.svg.length / 1024).toFixed(0)} KB `
        + `· วาด ${ms(performance.now() - t)} ms`);
      ctx.drawImage(wimg, 0, thaiH + 20, W, Math.round((W / d.w) * d.h));
    } else {
      report('⚠ ไม่เจอ .wn-host svg บนจอ — เพลงอาจเปิดมาเป็นมุมมองกระดาษไทยอย่างเดียว');
    }
    const png = await new Promise<Uint8Array>((res, rej) => {
      cv.toBlob((b2) => (b2 ? b2.arrayBuffer().then((ab) => res(new Uint8Array(ab)), rej) : rej(new Error('ว่าง'))), 'image/png');
    });
    await invoke('pipe_raw_file', png.slice());
    report(`เก็บภาพตัวอย่างไว้ที่ไฟล์ทดสอบแล้ว ${(png.length / 1024).toFixed(0)} KB `
      + `(แผ่นสากลติดมาด้วย: ${wn ? 'ใช่' : 'ไม่เจอ svg สากลบนจอ'})`);
  } catch (e) {
    report(`⚠ เก็บภาพตัวอย่างไม่สำเร็จ: ${String(e).slice(0, 120)}`);
  }

  // ── ★ ทำคลิปตัวอย่าง 3 แบบ ให้เจ้าของเลือกจากของจริง ───────────────
  try {
    const song = (window as any).__clipSong;
    const packCfg = (window as any).__clipPack;
    const bankRef = (window as any).__clipBank;
    if (!song || !packCfg || !bankRef) throw new Error('ไม่มีเพลง/ชุดเสียงให้อัด');

    const L = await import('./clip_layouts');
    const { renderClipAudio, wavBytes } = await import('./clip_audio');

    const spt = (60 / (Number(song.bpm) || 65)) / (Number(song.ticksPerHong) || 480);
    const tph = Number(song.ticksPerHong) || 480;
    const FPS = 30;
    // ★ แบบ "เต็มหน้า" ต้องยาวพอให้ **เห็นการเลื่อนหน้าจริง** (หน้าละ 6 บรรทัด
    //   ที่เพลงยาว ๆ ราว 48 ห้อง/หน้า) · แบบซูมสั้นกว่าได้เพราะเห็นผลทันที
    const secOf = (tag: string) => Math.min(
      tag.endsWith('page') ? 45 : 15, (Number(song.lengthTicks) || 0) * spt,
    );

    // ★★ ต้องแปลงเป็น **บิตแมป** ก่อนเอาไปวาดซ้ำทุกเฟรม ★★
    //   ภาพที่มาจาก SVG ถูก WebKit **วาดใหม่จาก XML ทุกครั้งที่ drawImage**
    //   คลิปสากล 20 วิ จึงใช้เวลา 245 วิ (410 ms/เฟรม) ทั้งที่วาดแค่ภาพเดียว
    //   createImageBitmap แปลงเป็นพิกเซลจริงครั้งเดียว แล้ววาดซ้ำแทบไม่กินเวลา
    const cachedBmp = await createImageBitmap(cached);
    const sheet: any = { img: cachedBmp, w: box.width, h: box.height, ...L.readSheet(paper) };
    // ★ แผ่นสากล = หลาย <svg> ใบ ใบละหนึ่งบรรทัด (ดู clip_layouts.readWesternSystem)
    const wnEls = [...document.querySelectorAll('.wn-host svg')] as SVGElement[];
    const systems = [];
    for (const el of wnEls.slice(0, 40)) {
      const d = svgDirect(el, css, vars);
      systems.push({
        img: await createImageBitmap(await decode(d.svg)),
        w: d.w, h: d.h, ...L.readWesternSystem(el),
      });
    }
    const western: any = systems.length ? { systems } : undefined;
    report(`ตัวอย่าง · กระดาษ ${sheet.lines.length} บรรทัด · สากล ${systems.length} บรรทัด`);

    // เสียงชุดเดียว ใช้ร่วมกันทั้งสามแบบ (เร็วมาก แต่ไม่ต้องทำซ้ำก็ได้)
    const a = await renderClipAudio(song, packCfg, bankRef, spt, { chingOn: true });
    const wav = wavBytes(a.buffer);
    await invoke('clip_audio', wav.slice());

    const title = String(song.title || 'ไม่ตั้งชื่อ');
    const rates = [...new Set((song.sections || []).map((x: any) => x.rate).filter(Boolean))];
    const subtitle = [song.instrumentTh, rates.join(' · ')].filter(Boolean).join(' · ');

    const cv = document.createElement('canvas');
    const c2 = cv.getContext('2d', { willReadFrequently: true })!;
    const slotTicks = tph / 4;

    // ★ เจ้าของสั่งเพิ่มแนวนอน (2026-08-19) — ทำตัวอย่างครบทั้งสองแนว
    // ★ `samples:<tag>` = ทำเฉพาะแบบนั้น (ไล่บั๊กจะได้ไม่ต้องรอทั้งชุด 8 อัน)
    const only = mode.startsWith('samples:') ? mode.slice(8) : '';
    for (const size of L.SIZES) {
      if (only && !size.tag.startsWith(only) && !only.includes(size.tag)) { /* ยังไม่ตัด */ }
      for (const lay of L.LAYOUTS) {
        if (only && lay.tag !== only) continue;
        const t0 = performance.now();
        // ★ เวลาที่ **ไม่ได้อยู่ในลูปเฟรม** ก็ต้องนับ ไม่งั้นผลรวมไม่ตรงกับเวลาจริง
        let tTile = 0; let tOpen = 0; let tClose = 0;
        cv.width = size.w; cv.height = size.h;
        const total = Math.round(secOf(lay.tag) * FPS);
        const tb = performance.now();
        await invoke('clip_begin', { width: size.w, height: size.h, fps: FPS });
        tOpen = performance.now() - tb;
        // ★★ คลังภาพชิ้น — วาดต้นฉบับใหม่ **เท่าขนาดที่จะใช้จริง** แล้วเก็บไว้ ★★
        //   เปลี่ยนหน้า/เปลี่ยนช่วงค่อยวาดใหม่ (ไม่กี่ครั้งต่อคลิป) · ระหว่างนั้นวาด 1:1
        //   จึงคมเท่าที่เอนจินวาดได้ ไม่ใช่ภาพขนาดจอที่ถูกขยาย
        const tiles = new Map<string, CanvasImageSource>();
        let made = 0; let lastStamp = '';
        let tDraw = 0; let tPix = 0; let tSend = 0; let tPlan = 0;
        // ★ ตัวเทียบ: ส่งไบต์ขนาดเท่ากันไปให้คำสั่งที่ **ไม่ทำอะไรเลย** ในลูปเดียวกัน
        //   ต่างกันมาก = ราคาอยู่ที่ตัวเข้ารหัส · เท่ากัน = ราคาอยู่ที่ท่อ
        let tCtl = 0; let nCtl = 0;
        for (let f = 0; f < total; f += 1) {
          const tick = (f / FPS) / spt;
          const base = {
            ctx: c2, W: size.w, H: size.h, sheet, western, title, subtitle,
            hongNo: Math.floor(tick / tph),
            slotTick: Math.floor(tick / slotTicks) * slotTicks,
            tiles,
          };
          // ★ คิดแผนใหม่เฉพาะตอนที่ช่องเวลาเปลี่ยน — `planFor` ต้องให้ตัววาดเดินจริง
          //   หนึ่งรอบ ถ้าทำทุกเฟรมเท่ากับวาดสองเท่าโดยเปล่าประโยชน์
          const stamp = `${base.hongNo}.${base.slotTick}`;
          const mp = performance.now();
          const need = stamp === lastStamp ? [] : L.planFor(lay.draw, base);
          tPlan += performance.now() - mp;
          for (const t of need) {
            if (tiles.has(t.key)) continue;
            const out = { w: Math.round(t.dst.w), h: Math.round(t.dst.h) };
            let svg: string;
            if (t.kind === 'thai') {
              svg = svgFor(paper, { w: box.width, h: box.height }, out, css, vars, t.crop);
            } else {
              svg = svgDirect(wnEls[t.sys!], css, vars, out.w).svg;
            }
            const tt = performance.now();
            tiles.set(t.key, await createImageBitmap(await decode(svg)));
            tTile += performance.now() - tt;
            made += 1;
          }
          lastStamp = stamp;
          const m0 = performance.now();
          lay.draw(base);
          const m1 = performance.now();
          const px = new Uint8Array(c2.getImageData(0, 0, size.w, size.h).data.buffer);
          const m2 = performance.now();
          await invoke('clip_frame', px);
          tDraw += m1 - m0; tPix += m2 - m1; tSend += performance.now() - m2;
          if (f % 30 === 15) {
            const dummy = new Uint8Array(size.w * size.h * 4);
            const c0 = performance.now();
            await invoke('pipe_raw', dummy);
            tCtl += performance.now() - c0; nCtl += 1;
          }
        }
        const tc = performance.now();
        await invoke('clip_end');
        await invoke('clip_mux');
        tClose = performance.now() - tc;
        const kept = await invoke<string>('clip_keep', { tag: `${lay.tag}-${size.tag}` });
        report(`${lay.name} · ${size.name} → ${kept.split('/').pop()} `
          + `(${((performance.now() - t0) / 1000).toFixed(1)} วิ · วาดต้นฉบับ ${made} ชิ้น)`);
        report(`   เวลาต่อเฟรม: วางภาพ ${(tDraw / total).toFixed(1)} ms · ดึงพิกเซล `
          + `${(tPix / total).toFixed(1)} ms · ส่ง ${(tSend / total).toFixed(1)} ms `
          + `· คิดแผน ${(tPlan / total).toFixed(1)} ms`);
        if (nCtl) report(`   ท่อเปล่าขนาดเท่ากัน (คำสั่งที่ไม่ทำอะไรเลย): ${(tCtl / nCtl).toFixed(1)} ms/ใบ`);
        report(`   นอกลูปเฟรม: วาดต้นฉบับ ${(tTile / 1000).toFixed(1)} วิ (${made} ชิ้น) `
          + `· เปิดคลิป ${(tOpen / 1000).toFixed(1)} วิ · ปิด+ต่อเสียง ${(tClose / 1000).toFixed(1)} วิ`);
      }
    }
    report('ทำตัวอย่างครบทุกแบบทั้งสองแนวแล้ว');
  } catch (e) {
    report(`⚠ ทำตัวอย่างไม่สำเร็จ: ${String(e).slice(0, 220)}`);
  }

  report('══ วัดฝั่งวาดเสร็จ ══');
}
